package com.smartgrading.backend.service.impl;
import com.smartgrading.backend.dto.GradeUpdateRequest; import com.smartgrading.backend.entity.*; import com.smartgrading.backend.repository.*; import com.smartgrading.backend.service.GradeService; import java.math.BigDecimal; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class GradeServiceImpl implements GradeService { private final GradeRepository repo; private final AiEvaluationRepository evaluations; private final AccessControlService access; public GradeServiceImpl(GradeRepository r,AiEvaluationRepository e,AccessControlService a){repo=r;evaluations=e;access=a;}
 @Transactional(readOnly=true) public List<Grade> byAnswer(Integer id){access.readableAnswer(id);return repo.findByAnswerId(id);}
 @Transactional public Grade update(Integer id,GradeUpdateRequest r){StudentAnswer answer=access.answerById(id);access.ownedAssignment(answer.getSubmission().getAssignment().getId());List<AiEvaluation> ev=evaluations.findByAnswerId(id);BigDecimal ai=ev.isEmpty()?null:ev.get(ev.size()-1).getAiScore();BigDecimal max=answer.getQuestion().getMaxMarks();check(r.teacherScore(),max,"teacher_score");check(r.finalScore(),max,"final_score");boolean override=Boolean.TRUE.equals(r.isOverridden())||(r.finalScore()!=null&&!r.finalScore().equals(ai));if(override&&r.finalScore()==null)throw new IllegalArgumentException("final_score is required when overriding the AI score");if(!override&&r.finalScore()!=null&&ai!=null&&!r.finalScore().equals(ai))throw new IllegalArgumentException("final_score can differ from AI score only when overridden");Grade g=repo.findByAnswerId(id).stream().findFirst().orElseGet(Grade::new);g.setAnswer(answer);g.setAiScore(ai);g.setTeacherScore(r.teacherScore());g.setFinalScore(override?r.finalScore():ai);g.setTeacherFeedback(r.teacherFeedback());g.setOverridden(override);return repo.save(g);}
 private void check(BigDecimal score,BigDecimal max,String field){if(score!=null&&(score.signum()<0||score.compareTo(max)>0))throw new IllegalArgumentException(field+" must be between 0 and max marks");}
}
